preset.frame_eqs_eel:
wave_mystery = wave_mystery + 0.25*tan(2.9*bass);
q1 = wave_mystery;
ob_r = ob_r + 0.8*sin(q1);
ob_g = ob_g + 0.7*sin(q1);
ob_b = ob_b - 0.6*sin(q1);
ib_r = ib_r - 0.5*sin(q1);
ib_g = ib_g + 0.5*sin(q1);
ib_b = ib_b +0.5*sin(q1);
wave_r = wave_r + (ob_r + ib_r)*0.5*sin(1.3*time);
wave_g = wave_g + (ib_g + ob_g)*0.5*sin(1.2*time);
wave_b = wave_b +  (ib_b + ob_b)*0.5*sin(1.1*time);

preset.pixel_eqs_eel:
kick = above(bass_att,kick)*2 + (1-above(bass_att,kick))*((kick-1.3)*0.9+1.3);
dx_r = equal(kick,2)*0.018*sin(6*time) + (1-equal(kick,2))*dx_r;
dy_r = equal(kick,2)*0.015*sin(7*time) + (1-equal(kick,2))*dy_r;

rot = rot + 0.3*(0.2*sin(0.5-rad)*5 - 0.2*sin(0.25*rad)*5) * kick;
dy = dy + 2*dy_r * 0.5*sin(0.8*time);
dx = dx + 2*dx_r * 0.5*sin(time);
warp = warp + if (below(kick,0), + 0.5*treb, q1);
zoom = zoom + 0.062*(1.22*cos((2*time)-2*rad)+0.5*cos(1.55*time));
